// LiveSpec.swift — parses design/*.json into a node tree. Part of the live-UI
// runtime: the UI is data, so changing it never needs a rebuild.
// Generated by build-ios. You normally never edit Sources/Runtime/.
import Foundation

typealias JSONObject = [String: Any]

struct LiveError: Error {
    let message: String
}

/// Loose JSON accessors. JSONSerialization hands back NSNumber / NSString /
/// NSArray / NSDictionary, so every accessor tolerates the "wrong" type.
enum LiveJSON {
    static func isBool(_ n: NSNumber) -> Bool {
        CFGetTypeID(n) == CFBooleanGetTypeID()
    }

    static func string(_ v: Any?) -> String? {
        if let s = v as? String { return s }
        if let n = v as? NSNumber {
            if isBool(n) { return n.boolValue ? "true" : "false" }
            let d = n.doubleValue
            if d == d.rounded(), abs(d) < 1e15 { return String(Int64(d)) }
            return n.stringValue
        }
        return nil
    }

    static func double(_ v: Any?) -> Double? {
        if let n = v as? NSNumber {
            if isBool(n) { return nil }
            return n.doubleValue
        }
        if let s = v as? String { return Double(s.trimmingCharacters(in: .whitespaces)) }
        return nil
    }

    /// nil for NaN/inf/huge values (Int(Double) would trap and crash the app).
    static func int(_ v: Any?) -> Int? {
        guard let d = double(v), d.isFinite, abs(d) < 1_000_000 else { return nil }
        return Int(d)
    }

    static func bool(_ v: Any?) -> Bool? {
        if let n = v as? NSNumber { return n.boolValue }
        if let s = v as? String {
            switch s.lowercased() {
            case "true", "yes", "1": return true
            case "false", "no", "0", "": return false
            default: return true
            }
        }
        return nil
    }

    static func object(_ v: Any?) -> JSONObject {
        (v as? JSONObject) ?? [:]
    }

    /// Dotted-path lookup: "items.0.name".
    static func lookup(_ root: Any?, _ path: String) -> Any? {
        var current: Any? = root
        for part in path.split(separator: ".") {
            let key = String(part)
            if let dict = current as? JSONObject {
                current = dict[key]
            } else if let arr = current as? [Any], let i = Int(key), i >= 0, i < arr.count {
                current = arr[i]
            } else {
                return nil
            }
        }
        return current
    }

    /// Replaces {{key}} with values from the scope. Unknown keys become "".
    static func interpolate(_ s: String, _ scope: LiveScope) -> String {
        guard s.contains("{{") else { return s }
        var out = ""
        var rest = Substring(s)
        while let open = rest.range(of: "{{") {
            out.append(contentsOf: rest[rest.startIndex..<open.lowerBound])
            let afterOpen = rest[open.upperBound...]
            guard let close = afterOpen.range(of: "}}") else {
                out.append(contentsOf: rest[open.lowerBound...])
                return out
            }
            let key = afterOpen[afterOpen.startIndex..<close.lowerBound]
                .trimmingCharacters(in: .whitespaces)
            out.append(string(scope.value(key)) ?? "")
            rest = afterOpen[close.upperBound...]
        }
        out.append(contentsOf: rest)
        return out
    }
}

/// Values visible to {{interpolation}}: repeat item, navigation params,
/// screen data, then global state (searched in that order).
struct LiveScope {
    var item: JSONObject = [:]
    var params: JSONObject = [:]
    var data: JSONObject = [:]
    var state: JSONObject = [:]
    var index: Int? = nil

    func value(_ key: String) -> Any? {
        if key == "index", let i = index { return i }
        if key == "number", let i = index { return i + 1 }
        let parts = key.split(separator: ".", maxSplits: 1).map(String.init)
        if parts.count == 2 {
            switch parts[0] {
            case "item": return LiveJSON.lookup(item, parts[1])
            case "params": return LiveJSON.lookup(params, parts[1])
            case "data": return LiveJSON.lookup(data, parts[1])
            case "state": return LiveJSON.lookup(state, parts[1])
            default: break
            }
        }
        if let v = LiveJSON.lookup(item, key) { return v }
        if let v = LiveJSON.lookup(params, key) { return v }
        if let v = LiveJSON.lookup(data, key) { return v }
        if let v = LiveJSON.lookup(state, key) { return v }
        return nil
    }
}

/// One element of the UI tree. A class so a repeat node can hold its template.
final class LiveNode: Identifiable {
    let type: String
    /// Stable key: the JSON "id", or a synthesized path when it is missing.
    let id: String
    let props: JSONObject
    let children: [LiveNode]
    let template: LiveNode?

    init(type: String, id: String, props: JSONObject, children: [LiveNode], template: LiveNode?) {
        self.type = type
        self.id = id
        self.props = props
        self.children = children
        self.template = template
    }

    static func parse(_ raw: Any?, path: String) -> LiveNode? {
        guard let obj = raw as? JSONObject else { return nil }
        let type = (obj["type"] as? String) ?? "unknown"
        let key = (obj["id"] as? String) ?? path
        var props = obj
        props.removeValue(forKey: "type")
        props.removeValue(forKey: "id")
        props.removeValue(forKey: "children")
        props.removeValue(forKey: "template")
        var kids: [LiveNode] = []
        if let raw = obj["children"] as? [Any] {
            for (i, child) in raw.enumerated() {
                if let node = parse(child, path: "\(key)/\(i)") { kids.append(node) }
            }
        }
        let template = parse(obj["template"], path: "\(key)/template")
        return LiveNode(type: type, id: key, props: props, children: kids, template: template)
    }
}

final class LiveScreen {
    let id: String
    let title: String?
    let titleDisplay: String
    let background: Any?
    let toolbar: [LiveNode]
    let data: JSONObject
    let body: LiveNode?

    init(id: String, json: JSONObject) {
        self.id = id
        title = json["title"] as? String
        titleDisplay = (json["titleDisplay"] as? String) ?? "large"
        background = json["background"]
        data = LiveJSON.object(json["data"])
        var items: [LiveNode] = []
        if let raw = json["toolbar"] as? [Any] {
            for (i, child) in raw.enumerated() {
                if let node = LiveNode.parse(child, path: "\(id).toolbar/\(i)") { items.append(node) }
            }
        }
        toolbar = items
        if let list = json["body"] as? [Any], list.count == 1, let only = list.first as? JSONObject,
           let kind = only["type"] as? String, kind == "list" || kind == "scroll" {
            // Already scrolls; wrapping a List in a ScrollView would collapse it to 0 pt.
            body = LiveNode.parse(only, path: "\(id).body/0")
        } else if let list = json["body"] as? [Any] {
            // A bare list of nodes means "scrolling column".
            let column: JSONObject = [
                "type": "scroll",
                "id": "\(id).body",
                "spacing": NSNumber(value: 16),
                "padding": NSNumber(value: 16),
                "children": list,
            ]
            body = LiveNode.parse(column, path: "\(id).body")
        } else {
            body = LiveNode.parse(json["body"], path: "\(id).body")
        }
    }
}

struct LiveTab: Identifiable {
    let id: String
    let title: String
    let symbol: String
    let screen: String
}

struct LiveTokens {
    var colors: JSONObject = [:]
    var colorsDark: JSONObject = [:]
    var fonts: JSONObject = [:]
    var spacing: JSONObject = [:]
    var radius: JSONObject = [:]
    var shadows: JSONObject = [:]
    var styles: JSONObject = [:]

    init() {}

    init(_ json: JSONObject) {
        colors = LiveJSON.object(json["colors"])
        colorsDark = LiveJSON.object(json["colorsDark"])
        fonts = LiveJSON.object(json["fonts"])
        spacing = LiveJSON.object(json["spacing"])
        radius = LiveJSON.object(json["radius"])
        shadows = LiveJSON.object(json["shadows"])
        styles = LiveJSON.object(json["styles"])
    }
}

final class LiveSpec {
    let name: String
    let tabs: [LiveTab]
    let root: String?
    let initialState: JSONObject
    let tint: Any?
    let colorScheme: String
    let tokens: LiveTokens
    let screens: [String: LiveScreen]

    init(name: String, tabs: [LiveTab], root: String?, initialState: JSONObject, tint: Any?,
         colorScheme: String, tokens: LiveTokens, screens: [String: LiveScreen]) {
        self.name = name
        self.tabs = tabs
        self.root = root
        self.initialState = initialState
        self.tint = tint
        self.colorScheme = colorScheme
        self.tokens = tokens
        self.screens = screens
    }

    static let empty = LiveSpec(name: "", tabs: [], root: nil, initialState: [:], tint: nil,
                                colorScheme: "system", tokens: LiveTokens(), screens: [:])

    /// Screen shown when there are no tabs.
    var rootScreen: String {
        if let r = root { return r }
        return screens.keys.sorted().first ?? ""
    }

    static func readJSON(_ url: URL) throws -> JSONObject {
        let data: Data
        do {
            data = try Data(contentsOf: url)
        } catch {
            throw LiveError(message: "\(url.lastPathComponent): cannot read file")
        }
        do {
            let any = try JSONSerialization.jsonObject(with: data, options: [])
            guard let obj = any as? JSONObject else {
                throw LiveError(message: "\(url.lastPathComponent): top level must be an object")
            }
            return obj
        } catch let e as LiveError {
            throw e
        } catch {
            let ns = error as NSError
            let detail = (ns.userInfo[NSDebugDescriptionKey] as? String) ?? ns.localizedDescription
            throw LiveError(message: "\(url.lastPathComponent): \(detail)")
        }
    }

    static func load(from dir: URL) throws -> LiveSpec {
        let fm = FileManager.default
        let app = try readJSON(dir.appendingPathComponent("app.json"))
        let tokensURL = dir.appendingPathComponent("tokens.json")
        var tokens = LiveTokens()
        if fm.fileExists(atPath: tokensURL.path) {
            tokens = LiveTokens(try readJSON(tokensURL))
        }

        var screens: [String: LiveScreen] = [:]
        let screensDir = dir.appendingPathComponent("screens")
        let names = ((try? fm.contentsOfDirectory(atPath: screensDir.path)) ?? [])
            .filter { $0.hasSuffix(".json") && !$0.hasPrefix(".") }
            .sorted()
        for file in names {
            let json = try readJSON(screensDir.appendingPathComponent(file))
            let fallbackId = String(file.dropLast(5))
            let id = (json["id"] as? String) ?? fallbackId
            screens[id] = LiveScreen(id: id, json: json)
        }

        var tabs: [LiveTab] = []
        if let raw = app["tabs"] as? [Any] {
            for (i, entry) in raw.enumerated() {
                let t = LiveJSON.object(entry)
                let screen = (t["screen"] as? String) ?? (t["id"] as? String) ?? ""
                tabs.append(LiveTab(id: (t["id"] as? String) ?? "tab\(i)",
                                    title: (t["title"] as? String) ?? screen.capitalized,
                                    symbol: (t["symbol"] as? String) ?? "circle",
                                    screen: screen))
            }
        }

        return LiveSpec(name: (app["name"] as? String) ?? "",
                        tabs: tabs,
                        root: app["root"] as? String,
                        initialState: LiveJSON.object(app["state"]),
                        tint: app["tint"],
                        colorScheme: (app["colorScheme"] as? String) ?? "system",
                        tokens: tokens,
                        screens: screens)
    }
}
